-- 122 · One spelling for every place.
--
-- City, state and market reached the filters as free text from a dozen doors
-- (the forms, the spreadsheet importer, Podio, Jotform and Zapier, the ingest
-- API, buyer self-registration, DispoGenius and InvestorBase), and no two of
-- them agreed. The Deals and Dispo "Market" menu, the Buyers State and City
-- menus and the vendor State menu listed "San Antonio", "san antonio tx",
-- "San Antonio, TX" and "San antonio tX" as four different places; the city
-- column on properties carried the state, and sometimes the ZIP, inside it.
--
-- From here on:
--   * properties.city holds only the city, spelled the way the Census spells
--     it ("McAllen", "DeSoto", "St. Louis"); properties.state is a USPS code
--     ("TX"); properties.zip is five digits. A state or ZIP typed into the
--     city column moves to its own column.
--   * buyers.markets and vendors.markets hold one of: a state code ("TX"),
--     "City, ST", "X County, ST" or a ZIP — one spelling each, no duplicates.
--     A bare city with no state stays a bare, canonical city; guessing its
--     state is the app's job (lib/market-geo), with the workspace's own
--     address history as evidence.
--   * vendors.city / vendors.state follow the property rules.
--   * deals.market is "City, ST" or a state code, the property's state filling
--     in a bare city's state.
--
-- Triggers on the four tables apply the rules to every write, whoever makes
-- it, and the backfill at the end rewrites the rows that are already there
-- (only the rows that change; a clean row is not touched). The app applies
-- the same rules on its own write paths and when it reads (lib/place-names.ts), so
-- the screens are right before this is applied and the database is right
-- after.
--
-- public.us_places is the reference: every Census incorporated place with
-- 5,000+ people and every county (the same data as app/lib/us-cities.ts, from
-- tools/gen-us-cities.mjs), so "mcallen" in Texas comes back "McAllen" rather
-- than "Mcallen". Public data; readable by any signed-in member.
--
-- Preview what the backfill will change before applying, if you like:
--
--   select p.id, p.city, p.state, p.zip, f.*
--     from public.properties p cross join lateral public.place_fix(p.city, p.state, p.zip) f
--    where (p.city, p.state, p.zip) is distinct from (f.city, f.state, f.zip);
--   select b.id, b.markets, public.place_markets(b.markets, null) as fixed
--     from public.buyers b where b.markets is distinct from public.place_markets(b.markets, null);

-- ---- the reference ----------------------------------------------------------

create or replace function public.place_key(p text)
returns text
language sql
immutable
parallel safe
set search_path = public, pg_temp
as $$
  -- Lower case, punctuation gone, one space between words, and the tokens
  -- people and the Census write differently folded: "Saint Louis", "St Louis"
  -- and "St. Louis" are all 'st louis'; "Ft Worth" is 'fort worth'. Spaces
  -- stay, because "La Mesa" and "Lamesa" are different towns.
  select nullif(string_agg(
    coalesce(('{"saint":"st","sainte":"ste","ft":"fort","mt":"mount","pt":"point","hts":"heights","spgs":"springs","jct":"junction"}'::jsonb) ->> w, w),
    ' ' order by ord), '')
  from unnest(string_to_array(btrim(regexp_replace(lower(coalesce(p, '')), '[^a-z0-9]+', ' ', 'g')), ' ')) with ordinality as t(w, ord)
  where w <> '';
$$;

create table if not exists public.us_places (
  state text not null,
  kind  text not null check (kind in ('city', 'county')),
  rank  integer not null,
  name  text not null,
  key   text generated always as (public.place_key(name)) stored,
  primary key (state, kind, rank)
);
create index if not exists us_places_state_key on public.us_places (state, key);
create index if not exists us_places_key on public.us_places (key);
alter table public.us_places enable row level security;
drop policy if exists us_places_read on public.us_places;
create policy us_places_read on public.us_places for select to authenticated using (true);
grant select on public.us_places to authenticated, service_role;

truncate public.us_places;
