-- ---- states -------------------------------------------------------------------

create or replace function public.place_state(p text)
returns text
language sql
immutable
parallel safe
set search_path = public, pg_temp
as $$
  -- A real USPS code or a state name, else null. "Tx." → TX, "texas" → TX,
  -- "xx" → null. Stricter than buyer_state_code (migration 61), which takes
  -- any two letters.
  with s as (select regexp_replace(regexp_replace(btrim(coalesce(p, '')), '\.+$', ''), '\s+', ' ', 'g') as t),
  names as (select '{
    "AL":"Alabama","AK":"Alaska","AZ":"Arizona","AR":"Arkansas","CA":"California","CO":"Colorado","CT":"Connecticut",
    "DE":"Delaware","DC":"District of Columbia","FL":"Florida","GA":"Georgia","HI":"Hawaii","ID":"Idaho","IL":"Illinois",
    "IN":"Indiana","IA":"Iowa","KS":"Kansas","KY":"Kentucky","LA":"Louisiana","ME":"Maine","MD":"Maryland",
    "MA":"Massachusetts","MI":"Michigan","MN":"Minnesota","MS":"Mississippi","MO":"Missouri","MT":"Montana",
    "NE":"Nebraska","NV":"Nevada","NH":"New Hampshire","NJ":"New Jersey","NM":"New Mexico","NY":"New York",
    "NC":"North Carolina","ND":"North Dakota","OH":"Ohio","OK":"Oklahoma","OR":"Oregon","PA":"Pennsylvania",
    "RI":"Rhode Island","SC":"South Carolina","SD":"South Dakota","TN":"Tennessee","TX":"Texas","UT":"Utah",
    "VT":"Vermont","VA":"Virginia","WA":"Washington","WV":"West Virginia","WI":"Wisconsin","WY":"Wyoming","PR":"Puerto Rico"
  }'::jsonb as j)
  select case
    when s.t = '' then null
    when length(s.t) = 2 and names.j ? upper(s.t) then upper(s.t)
    else (select k from jsonb_each_text(names.j) e(k, v) where lower(v) = lower(s.t) limit 1)
  end
  from s, names;
$$;

create or replace function public.place_state_name(p text)
returns text
language sql
immutable
parallel safe
set search_path = public, pg_temp
as $$
  select coalesce((select v from jsonb_each_text('{
    "AL":"Alabama","AK":"Alaska","AZ":"Arizona","AR":"Arkansas","CA":"California","CO":"Colorado","CT":"Connecticut",
    "DE":"Delaware","DC":"District of Columbia","FL":"Florida","GA":"Georgia","HI":"Hawaii","ID":"Idaho","IL":"Illinois",
    "IN":"Indiana","IA":"Iowa","KS":"Kansas","KY":"Kentucky","LA":"Louisiana","ME":"Maine","MD":"Maryland",
    "MA":"Massachusetts","MI":"Michigan","MN":"Minnesota","MS":"Mississippi","MO":"Missouri","MT":"Montana",
    "NE":"Nebraska","NV":"Nevada","NH":"New Hampshire","NJ":"New Jersey","NM":"New Mexico","NY":"New York",
    "NC":"North Carolina","ND":"North Dakota","OH":"Ohio","OK":"Oklahoma","OR":"Oregon","PA":"Pennsylvania",
    "RI":"Rhode Island","SC":"South Carolina","SD":"South Dakota","TN":"Tennessee","TX":"Texas","UT":"Utah",
    "VT":"Vermont","VA":"Virginia","WA":"Washington","WV":"West Virginia","WI":"Wisconsin","WY":"Wyoming","PR":"Puerto Rico"
  }'::jsonb) e(k, v) where k = public.place_state(p)), btrim(coalesce(p, '')));
$$;

-- The state a ZIP sits in, by its first three digits (USPS ranges; the same
-- table as lib/market-geo stateOfZip). Null when it is not a US ZIP.
create or replace function public.zip_state(p text)
returns text
language sql
immutable
parallel safe
set search_path = public, pg_temp
as $$
  select st from (values
    (5,5,'NY'),(6,9,'PR'),(10,27,'MA'),(28,29,'RI'),(30,38,'NH'),(39,49,'ME'),(50,59,'VT'),(60,69,'CT'),(70,89,'NJ'),
    (100,149,'NY'),(150,196,'PA'),(197,199,'DE'),(200,205,'DC'),(206,219,'MD'),(220,246,'VA'),(247,268,'WV'),
    (270,289,'NC'),(290,299,'SC'),(300,319,'GA'),(320,349,'FL'),(350,369,'AL'),(370,385,'TN'),(386,397,'MS'),(398,399,'GA'),
    (400,427,'KY'),(430,459,'OH'),(460,479,'IN'),(480,499,'MI'),(500,528,'IA'),(530,549,'WI'),(550,567,'MN'),(570,577,'SD'),
    (580,588,'ND'),(590,599,'MT'),(600,629,'IL'),(630,658,'MO'),(660,679,'KS'),(680,693,'NE'),(700,714,'LA'),(716,729,'AR'),
    (730,749,'OK'),(750,799,'TX'),(800,816,'CO'),(820,831,'WY'),(832,838,'ID'),(840,847,'UT'),(850,865,'AZ'),(870,884,'NM'),
    (885,885,'TX'),(889,898,'NV'),(900,961,'CA'),(967,968,'HI'),(970,979,'OR'),(980,994,'WA'),(995,999,'AK')
  ) r(lo, hi, st)
  where (regexp_match(btrim(coalesce(p, '')), '^(\d{3})\d{2}(-\d{4})?$'))[1]::int between lo and hi
  limit 1;
$$;

-- ---- spelling -----------------------------------------------------------------

-- Title case for a place the Census does not list: Mc + capital (McAllen, not
-- Macon), the capital after an apostrophe (O'Fallon), hyphens kept
-- (Winston-Salem), "of" and "the" small, "St." and "Ste." with their stop, and
-- a regional acronym (DFW) left alone.
create or replace function public.place_title(p text)
returns text
language plpgsql
immutable
parallel safe
set search_path = public, pg_temp
as $$
declare
  s text := regexp_replace(btrim(coalesce(p, '')), '\s+', ' ', 'g');
  o text := '';
  m text[];
  tok text;
  first boolean := true;
begin
  if s = '' then return ''; end if;
  if upper(s) in ('DFW','RGV','OKC','STL','NOLA','SWFL','NWA','ATL','PNW') then return upper(s); end if;
  for m in select regexp_matches(s, '([A-Za-z][A-Za-z'']*)|([^A-Za-z]+)', 'g') loop
    if m[1] is not null then
      tok := lower(m[1]);
      if not first and tok in ('of','the','and','at','on','in','by','for','du','des') then
        o := o || tok;
      elsif not first and m[1] ~ '^[A-Z]{2}$' and public.place_state(m[1]) is not null then
        -- "Washington DC" keeps its DC: a state code typed in capitals after
        -- the first word is an abbreviation, not a word to re-case.
        o := o || m[1];
      elsif tok ~ '^mc[a-z]' then
        o := o || 'Mc' || upper(substr(tok, 3, 1)) || substr(tok, 4);
      elsif tok ~ '^[a-z]''[a-z]' then
        o := o || upper(substr(tok, 1, 1)) || '''' || upper(substr(tok, 3, 1)) || substr(tok, 4);
      else
        o := o || upper(substr(tok, 1, 1)) || substr(tok, 2);
      end if;
      first := false;
    else
      o := o || m[2];
    end if;
  end loop;
  return regexp_replace(o, '\m(St|Ste)\M\.?(?=\s)', '\1.', 'g');
end $$;

-- The Census spelling for this city or county when the state is known and the
-- place is listed; the one spelling every state agrees on when the state is
-- not; title case otherwise.
create or replace function public.place_city(p_city text, p_state text)
returns text
language plpgsql
stable
set search_path = public, pg_temp
as $$
declare
  k text := public.place_key(p_city);
  st text := public.place_state(p_state);
  hit text;
begin
  if k is null then return null; end if;
  if st is not null then
    select u.name into hit from public.us_places u where u.state = st and u.key = k order by u.kind, u.rank limit 1;
  else
    select case when count(distinct u.name) = 1 then min(u.name) end into hit from public.us_places u where u.key = k;
  end if;
  return coalesce(hit, public.place_title(p_city));
end $$;

-- ---- splitting ------------------------------------------------------------------

-- The state and ZIP pulled out of a place written as one string, the city
-- canonical:
--   'San Antonio Tx'           → ('San Antonio', 'TX', null)
--   'san antonio, texas 78254' → ('San Antonio', 'TX', '78254')
--   'TX' / 'Texas'             → (null, 'TX', null)
--   '78254'                    → (null, null, '78254')
-- A trailing word is a state only when something precedes it, so a city that
-- shares a state's name ("Washington") stays a city unless it is the whole string.
create or replace function public.place_split(p text, out city text, out state text, out zip text)
language plpgsql
stable
set search_path = public, pg_temp
as $$
declare
  s text := regexp_replace(btrim(coalesce(p, '')), '\s+', ' ', 'g');
  z text;
  code text;
  parts text[];
  n integer;
  words text[];
  wn integer;
  k integer;
  c text;
begin
  if s = '' then return; end if;
  s := btrim(regexp_replace(s, ',?\s*\m(usa|u\.s\.a\.|united states( of america)?|us)\s*$', '', 'i'));
  s := regexp_replace(s, '\s+[-–—|/]\s+', ', ', 'g');
  -- A stray stop or comma at the end ("Ga 30331.") is not part of the place.
  s := regexp_replace(s, '[.,\s]+$', '');
  if s = '' then return; end if;

  z := (regexp_match(s, '[\s,]*\m(\d{5})(?:-\d{4})?\s*$'))[1];
  if z is not null then
    zip := z;
    s := btrim(regexp_replace(s, '[\s,]*\m\d{5}(?:-\d{4})?\s*$', ''));
    s := btrim(regexp_replace(s, ',$', ''));
  end if;
  if s = '' then return; end if;

  code := public.place_state(s);
  if code is not null then state := code; return; end if;

  parts := array(select btrim(x) from unnest(string_to_array(s, ',')) x where btrim(x) <> '');
  n := coalesce(array_length(parts, 1), 0);
  if n > 1 then
    code := public.place_state(parts[n]);
    if code is not null then state := code; parts := parts[1:n-1]; end if;
  end if;
  c := array_to_string(parts, ', ');

  if state is null then
    -- No comma: "San Antonio Tx", "San Antonio Texas", "Kansas City Missouri".
    words := string_to_array(c, ' ');
    wn := coalesce(array_length(words, 1), 0);
    foreach k in array array[3, 2, 1] loop
      if wn > k then
        code := public.place_state(array_to_string(words[wn-k+1:wn], ' '));
        if code is not null then
          state := code;
          c := array_to_string(words[1:wn-k], ' ');
          exit;
        end if;
      end if;
    end loop;
  end if;

  c := btrim(regexp_replace(c, '[,\s]+$', ''));
  -- "77469, TX": the ZIP came first and the tail check above missed it. Any
  -- other run of digits ("3222", a ZIP that lost a digit) is not a city.
  if zip is null and c ~ '^\d{5}(-\d{4})?$' then zip := substr(c, 1, 5); c := '';
  elsif c ~ '^[\d-]+$' then c := '';
  end if;
  if state is null and zip is not null then state := public.zip_state(zip); end if;
  if c <> '' then city := public.place_city(c, state); end if;
  return;
end $$;

-- The property-level fix: city holds only the city, state is a code, ZIP is
-- five digits. Whatever was typed into the wrong column moves to the right
-- one; a column that already had a value keeps it.
create or replace function public.place_fix(p_city text, p_state text, p_zip text, out city text, out state text, out zip text)
language plpgsql
stable
set search_path = public, pg_temp
as $$
declare
  typed text := public.place_state(p_state);
  raw_state text := btrim(coalesce(p_state, ''));
  -- "TX 78254" or "Texas, 78254" in the state column.
  sp_city text; sp_state text; sp_zip text;
  -- "San Antonio Tx" or "SAN ANTONIO, TX 78254" in the city column.
  fc_city text; fc_state text; fc_zip text;
  zraw text := regexp_replace(coalesce(p_zip, ''), '\s+', '', 'g');
begin
  if typed is null and raw_state <> '' then
    select s.city, s.state, s.zip into sp_city, sp_state, sp_zip from public.place_split(raw_state) s;
  end if;
  state := coalesce(typed, sp_state);
  if zraw ~ '^\d{5}(-\d{4})?$' then zip := substr(zraw, 1, 5);
  elsif zraw ~ '^\d{4}$' then zip := '0' || zraw; -- a leading zero lost to a spreadsheet
  end if;
  zip := coalesce(zip, sp_zip);
  select s.city, s.state, s.zip into fc_city, fc_state, fc_zip from public.place_split(p_city) s;
  city := coalesce(fc_city, sp_city);
  -- A city that is also a state's name ("Washington", "Nevada") is a city when
  -- the state column already names a different state; it is only a misfiled
  -- state when nothing else does. Keeps the fix stable: fixing a fixed row
  -- changes nothing.
  if city is null and fc_state is not null and state is not null and fc_state <> state then city := btrim(p_city); end if;
  state := coalesce(state, fc_state);
  zip := coalesce(zip, fc_zip);
  if city is not null then city := public.place_city(city, state); end if;
  return;
end $$;

-- ---- markets ------------------------------------------------------------------

-- One market token in its stored form: 'TX', 'San Antonio, TX', 'Hidalgo
-- County, TX', '78254', or a bare canonical city when no state is named and
-- the hint has none either. Blank in, null out.
create or replace function public.place_market(p text, p_hint_state text default null)
returns text
language plpgsql
stable
set search_path = public, pg_temp
as $$
declare
  r record;
  st text;
  nm text;
  m text[];
  kind_word text;
begin
  if p is null or btrim(p) = '' then return null; end if;
  select * into r from public.place_split(p);
  if r.city is null then return coalesce(r.zip, r.state); end if;
  st := coalesce(r.state, public.place_state(p_hint_state));
  if r.city ~* '\m(county|parish|borough|municipality|census area)\M' then
    -- A county keeps its word so "Bexar County" and the city of Bexar stay apart.
    nm := null;
    if st is not null then
      select u.name into nm from public.us_places u where u.state = st and u.key = public.place_key(r.city) order by u.kind, u.rank limit 1;
    end if;
    if nm is null then
      m := regexp_match(r.city, '^(.*?)\s*\m(county|parish|borough|municipality|census area)\M\s*$', 'i');
      if m is null then nm := public.place_title(r.city);
      else
        kind_word := case when lower(m[2]) = 'census area' then 'Census Area' else public.place_title(m[2]) end;
        nm := public.place_title(btrim(m[1])) || ' ' || kind_word;
      end if;
    end if;
  else
    nm := case when r.state is null and st is not null then public.place_city(r.city, st) else r.city end;
  end if;
  return case when st is not null then nm || ', ' || st else nm end;
end $$;

-- A buyer's or vendor's markets, each canonical, blanks dropped, duplicates
-- folded, order kept. One cell can hold several ("DFW, Houston", "TX; OK");
-- a comma followed by a state belongs to the place before it.
create or replace function public.place_markets(p text[], p_hint_state text default null)
returns text[]
language plpgsql
stable
set search_path = public, pg_temp
as $$
declare
  cell text;
  piece text;
  pieces text[];
  canon text;
  seen text[] := '{}';
  o text[] := '{}';
  prev text;
begin
  if p is null then return null; end if;
  foreach cell in array p loop
    pieces := '{}';
    foreach piece in array regexp_split_to_array(coalesce(cell, ''), '[;|,\n]') loop
      piece := btrim(piece);
      if piece = '' then continue; end if;
      prev := case when cardinality(pieces) > 0 then pieces[cardinality(pieces)] end;
      if prev is not null and public.place_state(piece) is not null and piece !~ '^\d'
         and public.place_state(prev) is null and position(',' in prev) = 0 then
        pieces[cardinality(pieces)] := prev || ', ' || piece;
      else
        pieces := pieces || piece;
      end if;
    end loop;
    foreach piece in array pieces loop
      canon := public.place_market(piece, p_hint_state);
      if canon is null or lower(canon) = any(seen) then continue; end if;
      seen := seen || lower(canon);
      o := o || canon;
    end loop;
  end loop;
  return o;
end $$;

grant execute on function public.place_key(text), public.place_state(text), public.place_state_name(text), public.zip_state(text),
  public.place_title(text), public.place_city(text, text), public.place_split(text), public.place_fix(text, text, text),
  public.place_market(text, text), public.place_markets(text[], text) to authenticated, service_role;

-- ---- every write, whoever makes it -------------------------------------------

-- properties_tidy (migration 9) ran initcap() over the city on every write,
-- which is what turned McAllen into "Mcallen" and DeSoto into "Desoto" in the
-- first place, and it fires after properties_place (triggers run in name
-- order). The city's spelling is place_city's job now; the tidy trigger keeps
-- the rest of what it did.
create or replace function public.tidy_property_fields() returns trigger
language plpgsql set search_path = public, pg_temp as $$
begin
  new.line1 := btrim(new.line1);
  if new.state is not null then new.state := upper(btrim(new.state)); end if;
  if new.apn is not null then new.apn := upper(btrim(new.apn)); end if;
  return new;
end $$;

create or replace function public.properties_place() returns trigger
language plpgsql set search_path = public, pg_temp as $$
declare f record;
begin
  select * into f from public.place_fix(new.city, new.state, new.zip);
  new.city := f.city; new.state := f.state; new.zip := f.zip;
  return new;
end $$;
revoke all on function public.properties_place() from public, anon, authenticated;
drop trigger if exists properties_place on public.properties;
create trigger properties_place before insert or update of city, state, zip on public.properties
  for each row execute function public.properties_place();

create or replace function public.buyers_markets() returns trigger
language plpgsql set search_path = public, pg_temp as $$
begin
  new.markets := coalesce(public.place_markets(new.markets, null), '{}');
  return new;
end $$;
revoke all on function public.buyers_markets() from public, anon, authenticated;
drop trigger if exists buyers_markets on public.buyers;
create trigger buyers_markets before insert or update of markets on public.buyers
  for each row execute function public.buyers_markets();

create or replace function public.vendors_place() returns trigger
language plpgsql set search_path = public, pg_temp as $$
declare f record;
begin
  select * into f from public.place_fix(new.city, new.state, null);
  new.city := f.city; new.state := f.state;
  new.markets := coalesce(public.place_markets(new.markets, new.state), '{}');
  return new;
end $$;
revoke all on function public.vendors_place() from public, anon, authenticated;
drop trigger if exists vendors_place on public.vendors;
create trigger vendors_place before insert or update of city, state, markets on public.vendors
  for each row execute function public.vendors_place();

create or replace function public.deals_market() returns trigger
language plpgsql set search_path = public, pg_temp as $$
begin
  -- A Podio "Market" of "San Antonio" on a Texas property is 'San Antonio, TX'.
  new.market := public.place_market(new.market, (select p.state from public.properties p where p.id = new.property_id));
  return new;
end $$;
revoke all on function public.deals_market() from public, anon, authenticated;
drop trigger if exists deals_market on public.deals;
create trigger deals_market before insert or update of market, property_id on public.deals
  for each row execute function public.deals_market();

-- ---- the rows already there -----------------------------------------------------

-- Properties one at a time: address_key is generated from the address parts,
-- so two rows that only differed by a misspelt city can become the same key.
-- When that is unique per workspace the second write is refused; the row is
-- then left as it was and named in the notices rather than failing the whole
-- migration.
do $$
declare r record; f record; n integer := 0; skipped integer := 0;
begin
  for r in select id, city, state, zip from public.properties loop
    select * into f from public.place_fix(r.city, r.state, r.zip);
    if (r.city, r.state, r.zip) is distinct from (f.city, f.state, f.zip) then
      begin
        update public.properties set city = f.city, state = f.state, zip = f.zip where id = r.id;
        n := n + 1;
      exception when unique_violation then
        skipped := skipped + 1;
        raise notice 'property % keeps city=% state=% zip=%: another property already has that address (%)', r.id, r.city, r.state, r.zip, sqlerrm;
      end;
    end if;
  end loop;
  raise notice 'properties: % rows rewritten, % left as they were', n, skipped;
end $$;

with fixed as (
  select b.id, public.place_markets(b.markets, null) as markets from public.buyers b where b.markets is not null
)
update public.buyers b set markets = fixed.markets
  from fixed where fixed.id = b.id and b.markets is distinct from fixed.markets;

with fixed as (
  select v.id, f.city, f.state, public.place_markets(v.markets, f.state) as markets
    from public.vendors v cross join lateral public.place_fix(v.city, v.state, null) f
)
update public.vendors v set city = fixed.city, state = fixed.state, markets = coalesce(fixed.markets, '{}')
  from fixed where fixed.id = v.id and (v.city, v.state, v.markets) is distinct from (fixed.city, fixed.state, coalesce(fixed.markets, '{}'));

with fixed as (
  select d.id, public.place_market(d.market, p.state) as market
    from public.deals d left join public.properties p on p.id = d.property_id
   where d.market is not null
)
update public.deals d set market = fixed.market
  from fixed where fixed.id = d.id and d.market is distinct from fixed.market;
